function showEntry(){if(adminMode||document.querySelector('.entry-overlay'))return;const face=localStorage.getItem('demo-face')==='1',layer=document.createElement('div');layer.className='entry-overlay';layer.innerHTML=`<div class="entry-content"><strong>monobank</strong><p>Демонстраційний вхід</p>${face?'<div class="face-scan" aria-label="Face ID"><svg viewBox="0 0 80 80" fill="none" stroke="currentColor" stroke-width="3"><path d="M24 6H12a6 6 0 0 0-6 6v12m50-18h12a6 6 0 0 1 6 6v12M6 56v12a6 6 0 0 0 6 6h12m32 0h12a6 6 0 0 0 6-6V56M25 28v8m30-8v8M40 28v18h-6m-7 8q13 12 26 0"/></svg></div><p>Face ID</p>':'<form class="entry-pin"><label for="entry-code">Введіть PIN-код</label><input id="entry-code" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required autocomplete="off"><p role="alert"></p><button class="primary">Увійти</button></form>'}</div>`;document.body.append(layer);$('#app').inert=true;$('#nav').inert=true;const unlock=()=>{layer.remove();$('#app').inert=false;$('#nav').inert=false};if(face)setTimeout(unlock,1100);else{const form=layer.querySelector('form');form.onsubmit=e=>{e.preventDefault();if(form.querySelector('input').value===localStorage.getItem('demo-pin'))unlock();else{form.querySelector('[role=alert]').textContent='Невірний PIN-код';form.querySelector('input').value=''}};form.querySelector('input').focus()}}
