const renderBeforeContinuity=render;render=function(){renderBeforeContinuity();document.body.classList.toggle('document-open',!adminMode&&['receipt','file'].includes(route.page));if(route.page==='file'&&!adminMode){const f=state.files.find(f=>f.id===route.id),stage=$('.receipt-fit');if(f?.type==='application/pdf'&&stage)previewReceipt(f).then(pages=>{if(!stage.isConnected)return;stage.replaceChildren(...pages.map((src,i)=>{const img=new Image();img.src=src;img.alt='Квитанція · сторінка '+(i+1);return img}));stage.setAttribute('aria-busy','false')}).catch(e=>{if(stage.isConnected){stage.textContent=e.message;stage.setAttribute('aria-busy','false')}})}if(!loading&&!sharedLoading&&!adminMode&&!window.entryChecked){window.entryChecked=true;if(localStorage.getItem('demo-entry')==='1')showEntry()}};
// Persistent navigation: do not replace identical icon markup on every render.
const syncBeforeContinuity=syncNavigation;syncNavigation=function(){const nav=$('#nav'),old=[...nav.children];syncBeforeContinuity();const fresh=[...nav.children];if(old.length===fresh.length)fresh.forEach((node,i)=>{if(old[i].dataset.page===node.dataset.page&&old[i].innerHTML===node.innerHTML){old[i].className=node.className;for(const attr of ['aria-current','aria-selected']){if(node.hasAttribute(attr))old[i].setAttribute(attr,node.getAttribute(attr));else old[i].removeAttribute(attr)}node.replaceWith(old[i])}})};
